// Resolver o os_id real (interno Bom Saldo = 7+ dígitos)
const trigger = $('Trigger').first().json;
const supabase = $input.first().json;

// Prioridade: os_id_bomsaldo do Supabase > os_id do trigger
const osIdSupa = String(supabase.os_id_bomsaldo || '').replace(/[^0-9]/g, '');
const osIdTrigger = String(trigger.os_id || '').replace(/[^0-9]/g, '');

let osIdReal;
if (osIdSupa.length >= 7) {
  osIdReal = osIdSupa;
} else if (osIdTrigger.length >= 7) {
  osIdReal = osIdTrigger;
} else {
  return [{ json: { error: `VANDA: os_id '${trigger.os_id}' parece ser o código visível da OS, não o ID interno. O ID interno tem 7+ dígitos. Chame 'buscarContexto' para recuperar o os_id correto.` } }];
}

// Pegar hora_entrada/saida do Supabase se não vieram no trigger
const horaEntrada = trigger.hora_entrada || supabase.hora_entrada || null;
const horaSaida = trigger.hora_saida || supabase.hora_saida || null;

const emGarantia = (trigger.em_garantia !== undefined && trigger.em_garantia !== null && trigger.em_garantia !== '') 
  ? (trigger.em_garantia === 'true' || trigger.em_garantia === true)
  : (supabase.em_garantia === true);

const tipoServico = trigger.tipo_servico || supabase.tipo_servico || null;

const equipamento = trigger.equipamento || supabase.equipamento || null;
const marca = trigger.marca || supabase.marca || null;
const modelo = trigger.modelo || supabase.modelo || null;
const defeito = trigger.defeito || supabase.defeito || null;
const solucao = trigger.solucao || supabase.solucao || null;

// Laudo / Relatório técnico: se não vier no trigger, tentar ler do Supabase ou montar
let relatorioTecnico = trigger.relatorio_tecnico || trigger.laudo || supabase.relatorio_tecnico || null;
if (!relatorioTecnico && defeito && solucao) {
  relatorioTecnico = `Equipamento: ${equipamento || 'Não informado'}. Defeito: ${defeito}. Solução: ${solucao}.`;
}

return [{ json: {
  ...trigger,
  os_id: osIdReal,
  os_codigo: trigger.os_codigo || supabase.os_codigo,
  hora_entrada: horaEntrada,
  hora_saida: horaSaida,
  em_garantia: emGarantia,
  tipo_servico: tipoServico,
  equipamento: equipamento,
  marca: marca,
  modelo: modelo,
  defeito: defeito,
  solucao: solucao,
  relatorio_tecnico: relatorioTecnico,
  laudo: relatorioTecnico,
  produtos_json_supabase: supabase.produtos_json,
  servicos_json_supabase: supabase.servicos_json
} }];

const triggerParams = $('Resolver OS ID').first().json;
const osResp = $input.first().json;

if (triggerParams.error) {
  return [{ json: { error: triggerParams.error } }];
}

if (!osResp || osResp.status === 'error' || !osResp.data) {
  const dt = osResp ? (osResp.message || JSON.stringify(osResp)) : 'erro desconhecido';
  return [{ json: { error: 'FALHA GRAVE AO BUSCAR OS. Erro API: ' + dt } }];
}

const osAtual = osResp.data;

let produtos = [];
let servicos = [];
// Pegar JSON do trigger ou tentar fallback do Supabase
try { produtos = typeof triggerParams.produtos_json === 'string' ? JSON.parse(triggerParams.produtos_json) : (triggerParams.produtos_json || []); } catch(e) {}
if (produtos.length === 0 && triggerParams.produtos_json_supabase) {
  try { produtos = typeof triggerParams.produtos_json_supabase === 'string' ? JSON.parse(triggerParams.produtos_json_supabase) : triggerParams.produtos_json_supabase; } catch(e) {}
}

try { servicos = typeof triggerParams.servicos_json === 'string' ? JSON.parse(triggerParams.servicos_json) : (triggerParams.servicos_json || []); } catch(e) {}
if (servicos.length === 0 && triggerParams.servicos_json_supabase) {
  try { servicos = typeof triggerParams.servicos_json_supabase === 'string' ? JSON.parse(triggerParams.servicos_json_supabase) : triggerParams.servicos_json_supabase; } catch(e) {}
}

const emGarantia = triggerParams.em_garantia === 'true' || triggerParams.em_garantia === true;

// Propriedades extras para o Supabase
const sitId = String(triggerParams.situacao_id || osAtual.situacao_id || '6237497');
const isCancelada = sitId === '6237500';
const isFechada = sitId === '6237499';
const isFechamento = isCancelada || isFechada;

const extraOutput = {
  is_fechamento: isFechamento,
  supabase_status_os: isCancelada ? 'cancelada' : (isFechada ? 'concluida' : 'aberta'),
  supabase_fase_ia: isFechamento ? 'fechado' : 'coleta_tecnica',
  motivo_cancelamento: triggerParams.motivo_cancelamento || null
};


// ── Timestamps de chegada e saída ──
const parseTimeStr = (ts) => {
  if (!ts) return null;
  if (ts.includes('T')) {
    const d = new Date(ts);
    if (!isNaN(d.getTime())) return { h: d.getHours(), m: d.getMinutes(), d };
  }
  let clean = ts.toLowerCase().replace(/[^0-9h:]/g, '');
  if (clean.includes(':')) {
    const parts = clean.split(':');
    return { h: parseInt(parts[0], 10), m: parseInt(parts[1], 10) };
  } else if (clean.includes('h')) {
    const parts = clean.split('h');
    return { h: parseInt(parts[0], 10), m: parseInt(parts[1] || '0', 10) };
  } else if (clean.length === 4) {
    return { h: parseInt(clean.substring(0,2), 10), m: parseInt(clean.substring(2,4), 10) };
  }
  return null;
};

const formatBR = (ts) => {
  if (!ts) return null;
  const t = parseTimeStr(ts);
  if (!t || isNaN(t.h)) return ts;
  if (t.d) {
    return t.d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  }
  return `${String(t.h).padStart(2,'0')}:${String(t.m).padStart(2,'0')}`;
};

const checkinBR = formatBR(triggerParams.hora_entrada);
const checkoutBR = formatBR(triggerParams.hora_saida);

let tempoMin = null;
let tempoFormatado = '';
const tIn = parseTimeStr(triggerParams.hora_entrada);
const tOut = parseTimeStr(triggerParams.hora_saida);

if (tIn && tOut && !isNaN(tIn.h) && !isNaN(tOut.h)) {
  let inMins = tIn.h * 60 + tIn.m;
  let outMins = tOut.h * 60 + tOut.m;
  if (outMins < inMins) outMins += 24 * 60; // virou o dia
  tempoMin = outMins - inMins;

  if (!isNaN(tempoMin)) {
    const h = Math.floor(tempoMin / 60);
    const m = tempoMin % 60;
    if (h > 0 && m > 0) tempoFormatado = `${h}h${m} / ${tempoMin} min`;
    else if (h > 0) tempoFormatado = `${h}h / ${tempoMin} min`;
    else tempoFormatado = `${tempoMin} min`;
  } else {
    tempoMin = null;
  }
}

// Relatório técnico + timestamps
let obsInterna = triggerParams.relatorio_tecnico || triggerParams.laudo || osAtual.observacoes_interna || '';

const tsLinhas = [];
if (checkinBR && !obsInterna.includes('[CHEGADA:')) tsLinhas.push(`[CHEGADA: ${checkinBR}]`);
if (checkoutBR && !obsInterna.includes('[SAÍDA:') && !obsInterna.includes('[SAIDA:')) tsLinhas.push(`[SAÍDA: ${checkoutBR}]`);
if (tempoFormatado && !obsInterna.includes('[TEMPO:')) tsLinhas.push(`[TEMPO: ${tempoFormatado}]`);

if (tsLinhas.length > 0) {
  obsInterna = (obsInterna ? obsInterna + '\n' : '') + tsLinhas.join('\n');
}

// Injetar motivo de cancelamento se for uma OS cancelada
if (String(triggerParams.situacao_id || '') === '6237500' && triggerParams.motivo_cancelamento) {
  const tagMotivo = `[MOTIVO CANCELAMENTO: ${triggerParams.motivo_cancelamento}]`;
  if (!obsInterna.includes('[MOTIVO CANCELAMENTO:')) {
    obsInterna = tagMotivo + '\n' + obsInterna;
  }
}

// Injetar motivo de cancelamento se for uma OS cancelada
if (String(triggerParams.situacao_id || '') === '6237500' && triggerParams.motivo_cancelamento) {
  const tagMotivo = `[MOTIVO CANCELAMENTO: ${triggerParams.motivo_cancelamento}]`;
  if (!obsInterna.includes('[MOTIVO CANCELAMENTO:')) {
    obsInterna = tagMotivo + '\n' + obsInterna;
  }
}

// Injetar motivo de cancelamento se for uma OS cancelada
if (String(triggerParams.situacao_id || '') === '6237500' && triggerParams.motivo_cancelamento) {
  const tagMotivo = `[MOTIVO CANCELAMENTO: ${triggerParams.motivo_cancelamento}]`;
  if (!obsInterna.includes('[MOTIVO CANCELAMENTO:')) {
    obsInterna = tagMotivo + '\n' + obsInterna;
  }
}

const payload = {
  codigo: osAtual.codigo,
  cliente_id: osAtual.cliente_id,
  data: osAtual.data || new Date().toISOString().split('T')[0],
  observacoes: triggerParams.observacoes_orientacao || osAtual.observacoes || '',
  observacoes_interna: obsInterna.trim(),
  situacao_id: sitId
};

// Equipamentos
let equipamentosArray = osAtual.equipamentos || [];
if (triggerParams.equipamento) {
  equipamentosArray = [{
    equipamento: {
      equipamento: triggerParams.equipamento || '',
      marca: triggerParams.marca || '',
      modelo: triggerParams.modelo || '',
      defeitos: triggerParams.defeito || '',
      solucao: triggerParams.solucao || '',
      laudo: triggerParams.relatorio_tecnico || triggerParams.laudo || ''
    }
  }];
}
if (equipamentosArray.length > 0) payload.equipamentos = equipamentosArray;

// Produtos (manter existentes + novos)
let produtosArray = [];
if (osAtual.produtos) {
  osAtual.produtos
    .filter(p => p.produto.produto_id && p.produto.produto_id !== '')
    .forEach(p => {
      produtosArray.push({ produto: {
        produto_id: p.produto.produto_id,
        variacao_id: p.produto.variacao_id,
        quantidade: String(p.produto.quantidade),
        valor_venda: emGarantia ? '0' : String(p.produto.valor_venda),
        tipo_desconto: p.produto.tipo_desconto || 'R$',
        desconto_valor: String(p.produto.desconto_valor || '0'),
        desconto_porcentagem: String(p.produto.desconto_porcentagem || '0')
      }});
    });
}
produtos.forEach(p => {
  const pid = p.produto_id || p.id;
  if (!pid || pid === '') return;
  produtosArray.push({ produto: {
    produto_id: pid,
    variacao_id: p.variacao_id || '',
    quantidade: String(p.quantidade || '1'),
    valor_venda: emGarantia ? '0' : String(p.valor_venda ?? '0'),
    tipo_desconto: 'R$', desconto_valor: '0', desconto_porcentagem: '0'
  }});
});
if (produtosArray.length > 0) payload.produtos = produtosArray;

// Serviços (manter existentes + novos)
let servicosArray = [];
if (osAtual.servicos) {
  osAtual.servicos
    .filter(s => s.servico.servico_id && s.servico.servico_id !== '')
    .forEach(s => {
      servicosArray.push({ servico: {
        servico_id: s.servico.servico_id,
        quantidade: String(s.servico.quantidade),
        valor_venda: emGarantia ? '0' : String(s.servico.valor_venda),
        tipo_desconto: s.servico.tipo_desconto || 'R$',
        desconto_valor: String(s.servico.desconto_valor || '0'),
        desconto_porcentagem: String(s.servico.desconto_porcentagem || '0')
      }});
    });
}
servicos.forEach(s => {
  const sid = s.servico_id || s.id;
  if (!sid || sid === '') return;
  servicosArray.push({ servico: {
    servico_id: sid,
    quantidade: String(s.quantidade || '1'),
    valor_venda: emGarantia ? '0' : String(s.valor_venda ?? '0'),
    tipo_desconto: 'R$', desconto_valor: '0', desconto_porcentagem: '0'
  }});
});
if (servicosArray.length > 0) payload.servicos = servicosArray;

// Atributos OS
const camposExtras = [];
if (triggerParams.observacoes_orientacao) {
  camposExtras.push({ atributo_os: { atributo_id: '58530', valor: triggerParams.observacoes_orientacao } });
}
if (triggerParams.relatorio_tecnico || triggerParams.laudo) {
  camposExtras.push({ atributo_os: { atributo_id: '58528', valor: triggerParams.relatorio_tecnico || triggerParams.laudo } });
}
const tipoServico = emGarantia ? 'Garantia' : (triggerParams.tipo_servico || '');
if (tipoServico) {
  camposExtras.push({ atributo_os: { atributo_id: '58529', valor: tipoServico } });
}
if (camposExtras.length > 0) payload.atributos_os = camposExtras;


// ── Validação de integridade: bloquear se contexto tinha itens mas array ficou vazio ──
const contextoTinhaProdutos = Array.isArray(produtos) && produtos.some(p => p.produto_id || p.id);
const contextoTinhaServicos = Array.isArray(servicos) && servicos.some(s => s.servico_id || s.id);
const supabaseTinhaProdutos = Array.isArray(triggerParams.produtos_json_supabase) && triggerParams.produtos_json_supabase.length > 0;
const supabaseTinhaServicos = Array.isArray(triggerParams.servicos_json_supabase) && triggerParams.servicos_json_supabase.length > 0;

if ((contextoTinhaProdutos || supabaseTinhaProdutos) && produtosArray.length === 0) {
  return [{ json: {
    error: 'ERRO_INTEGRIDADE: Contexto tinha produtos salvos mas nenhum com produto_id válido chegou ao payload. Verifique produtos_json no Supabase.',
    error_code: 'PRODUTOS_SEM_ID',
    sucesso: false
  }}];
}
if ((contextoTinhaServicos || supabaseTinhaServicos) && servicosArray.length === 0) {
  return [{ json: {
    error: 'ERRO_INTEGRIDADE: Contexto tinha serviços salvos mas nenhum com servico_id válido chegou ao payload. Verifique servicos_json no Supabase.',
    error_code: 'SERVICOS_SEM_ID',
    sucesso: false
  }}];
}

// Garantia — pagamento zerado
if (emGarantia) {
  payload.pagamentos = [{ pagamento: { data_vencimento: new Date().toISOString().split('T')[0], valor: '0.00', forma_pagamento_id: '4366641' } }];
  return [{ json: { os_id: triggerParams.os_id, os_codigo: triggerParams.os_codigo, payload, tempo_atendimento_min: tempoMin, ...extraOutput } }];
}

// Calcular total
let sumTotal = 0;
produtosArray.forEach(p => {
  sumTotal += parseFloat(p.produto.quantidade || 0) * parseFloat(p.produto.valor_venda || 0);
});
servicosArray.forEach(s => {
  sumTotal += parseFloat(s.servico.quantidade || 0) * parseFloat(s.servico.valor_venda || 0);
});

// Forma de pagamento
let formaId = '4366641';
const tp = (triggerParams.tipo_pagamento || '').toLowerCase();
if (tp.includes('pix') && (tp.includes('nubank') || (!tp.includes('inter') && !tp.includes('cora')))) formaId = '4354384';
else if (tp.includes('pix') && tp.includes('inter')) formaId = '4377571';
else if (tp.includes('pix') && tp.includes('cora')) formaId = '5108978';
else if (tp.includes('dinheiro') || tp.includes('especie') || tp.includes('espécie')) formaId = '4354377';
else if (tp.includes('boleto') || tp.includes('faturad') || tp.includes('escritorio')) formaId = '4366641';
else if (osAtual.pagamentos?.length > 0) formaId = osAtual.pagamentos[0].pagamento.forma_pagamento_id || formaId;

payload.pagamentos = [{ pagamento: {
  data_vencimento: new Date().toISOString().split('T')[0],
  valor: String(Math.max(sumTotal, 0).toFixed(2)),
  forma_pagamento_id: formaId
}}];

return [{ json: { os_id: triggerParams.os_id, os_codigo: triggerParams.os_codigo, payload, tempo_atendimento_min: tempoMin, ...extraOutput } }];

const payloadJson = $('Montar Payload').first().json;
if (payloadJson.error) {
  return [{ json: { sucesso: false, resultado: payloadJson.error } }];
}

// Se não for fechamento, retornar sucesso imediatamente sem fazer GET de validação
if (!payloadJson.is_fechamento) {
  return [{ json: {
    sucesso: true,
    resultado: `OS ${payloadJson.os_codigo} atualizada parcialmente com sucesso.`,
    os_codigo: payloadJson.os_codigo,
    os_id: payloadJson.os_id,
    is_fechamento: false
  } }];
}

const putData = $('PUT Atualizar OS').first().json;
if (putData.status === 'error' || putData.error || (putData.statusCode && putData.statusCode >= 400)) {
  const detalheErro = putData.message || putData.error || JSON.stringify(putData);
  return [{ json: {
    sucesso: false,
    resultado: 'Erro fatal ao SALVAR a OS no Bom Saldo. Detalhes: ' + detalheErro,
    erro_put: true
  } }];
}

const codigo = payloadJson.os_codigo;
const osId = payloadJson.os_id;
const payloadEnviado = payloadJson.payload;

// Extrair IDs esperados para confirmacao
const produtosEnviados = payloadEnviado.produtos || [];
const servicosEnviados = payloadEnviado.servicos || [];
const prodIdEsperados = produtosEnviados.map(p => String(p.produto.produto_id)).filter(Boolean);
const svcIdEsperados = servicosEnviados.map(s => String(s.servico.servico_id)).filter(Boolean);

// -- GET autenticado de confirmacao pos-PUT --
let sucesso_confirmacao = false;
let confirmacao_produtos = true;
let confirmacao_servicos = true;
let erro_confirmacao = null;
let getOsData = null;

try {
  const getResp = await $helpers.httpRequest({
    method: 'GET',
    url: `https://bomsaldo.com/api/ordens_servicos/${osId}/`,
    headers: {
      'access-token': '698a9f9846f8ea6d2b3a59d5cb99f4a9e32c17e8',
      'secret-access-token': '874ac39b56dcf8a7b87e9bdafe88f833d0155c7a',
      'Accept': 'application/json'
    }
  });

  getOsData = getResp.data || null;

  if (getOsData) {
    // Validar produto_id especifico, nao apenas length
    if (prodIdEsperados.length > 0) {
      const produtosConfirmados = (getOsData.produtos || []).map(p => String(p.produto && p.produto.produto_id || ''));
      const todosPresentes = prodIdEsperados.every(pid => produtosConfirmados.includes(pid));
      confirmacao_produtos = todosPresentes;
    }
    // Validar servico_id especifico
    if (svcIdEsperados.length > 0) {
      const servicosConfirmados = (getOsData.servicos || []).map(s => String(s.servico && s.servico.servico_id || ''));
      const todosPresentes = svcIdEsperados.every(sid => servicosConfirmados.includes(sid));
      confirmacao_servicos = todosPresentes;
    }
    sucesso_confirmacao = confirmacao_produtos && confirmacao_servicos;
  } else {
    // GET retornou sem data: nao assumir sucesso
    erro_confirmacao = 'GET pos-PUT retornou sem data';
    sucesso_confirmacao = false;
  }
} catch(e) {
  // Falha no GET: NENHUMA ASSUMPCAO DE SUCESSO
  erro_confirmacao = e.message || String(e);
  sucesso_confirmacao = false;
}

// -- PATCH Supabase: laudo --
let supabase_laudo_sync = false;
let erro_supabase_laudo = null;
const obs = payloadEnviado.observacoes_interna;

if (obs && codigo) {
  try {
    await $helpers.httpRequest({
      method: 'PATCH',
      url: 'https://bnghvmromtukmflzeojd.supabase.co/rest/v1/ordens_servico',
      headers: {
        'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImJuZ2h2bXJvbXR1a21mbHplb2pkIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ0ODIwODIsImV4cCI6MjA5MDA1ODA4Mn0.wzB2T9lMzWI-4ilu7MXREbf9w-loCoZxPLrE1WAzHTo',
        'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImJuZ2h2bXJvbXR1a21mbHplb2pkIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQ0ODIwODIsImV4cCI6MjA5MDA1ODA4Mn0.wzB2T9lMzWI-4ilu7MXREbf9w-loCoZxPLrE1WAzHTo',
        'Content-Type': 'application/json'
      },
      qs: { 'os_codigo': 'eq.' + codigo },
      body: { 'relatorio_tecnico': obs }
    });
    supabase_laudo_sync = true;
  } catch(e) {
    erro_supabase_laudo = e.message || String(e);
  }
}

// -- Resultado final --
if (!sucesso_confirmacao) {
  const motivo = erro_confirmacao
    ? `Erro no GET de confirmacao: ${erro_confirmacao}`
    : `Itens esperados nao encontrados. Produtos OK: ${confirmacao_produtos}, Servicos OK: ${confirmacao_servicos}`;

  return [{ json: {
    sucesso: false,
    resultado: `OS ${codigo} atualizada no Bom Saldo, mas nao foi possivel confirmar que produtos/servicos foram registrados. NAO declarar OS concluida. Motivo: ${motivo}`,
    os_codigo: codigo,
    os_id: osId,
    erro_confirmacao_get: !sucesso_confirmacao,
    confirmacao_produtos,
    confirmacao_servicos,
    produtos_id_esperados: prodIdEsperados,
    servicos_id_esperados: svcIdEsperados,
    erro_confirmacao,
    supabase_laudo_sync,
    erro_supabase_laudo
  } }];
}

return [{ json: {
  sucesso: true,
  resultado: `OS ${codigo} finalizada e confirmada com sucesso no Bom Saldo. Produtos e servicos verificados.`,
  os_codigo: codigo,
  os_id: osId,
  tempo_atendimento_min: payloadJson.tempo_atendimento_min,
  confirmacao_produtos,
  confirmacao_servicos,
  sucesso_confirmacao,
  supabase_laudo_sync,
  erro_supabase_laudo
} }];
